// Sender brand image derived from Resources/Assets.xcassets/AppIcon.appiconset/AppIcon-1024.png.
// Public PNG asset for sender-domain identity setup; it does not force inbox avatars.
const imageBase64 = "";

export function bookingEmailAvatarResponse(): Response {
  const bytes = Uint8Array.from(atob(imageBase64), c => c.charCodeAt(0));
  return new Response(bytes, { headers: {
    "content-type": "image/png", "cache-control": "public, max-age=86400",
    "x-content-type-options": "nosniff",
  }});
}
